mapper.select:
SELECT 
  FROM biz29_account
       LEFT OUTER JOIN sys15_corp       ON sys15_corp_id = biz29_corp_id
       LEFT OUTER JOIN ast01_class_tree ON ast01_class_tree_id = biz29_ast_class_tree_id
 WHERE biz29_account_id = #{accountId}
   AND biz29_company_id = #{companyId}

SELECT COUNT(*)
  FROM biz29_account
 WHERE biz29_account_id = #{accountId}
   AND biz29_company_id = #{companyId}

mapper.update:
UPDATE biz29_account
   SET biz29_corp_id            = #{r.corpId}
     , biz29_start_date         = #{r.startDate}
     , biz29_bank_cd            = #{r.bankCd}
     , biz29_account_no         = #{r.accountNo}
     , biz29_account_nm         = #{r.accountNm}
     , biz29_ast_class_tree_id  = #{r.astClassTreeId}
     , biz29_note               = #{r.note}
 WHERE biz29_account_id = #{r.accountId}
   AND biz29_company_id = #{companyId}

mapper.delete:
DELETE FROM biz29_account
 WHERE biz29_account_id = #{accountId}
   AND biz29_company_id = #{companyId}
